export const catalogs = {
  0: sunday,
  1: mondayEffects.map(([effect, type], index) => [sunday[index][0], effect, type]),
  2: tuesdayEffects.map(([effect, type], index) => [sunday[index][0], effect, type]),
  3: wednesdayEffects.map(([effect, type], index) => [sunday[index][0], effect, type]),
  4: thursdayEffects.map(([effect, type], index) => [sunday[index][0], effect, type]),
  5: fridayEffects.map(([effect, type], index) => [sunday[index][0], effect, type]),
  6: saturdayEffects.map(([effect, type], index) => [sunday[index][0], effect, type]),
};

const rulers = {
  0: { day: [1, 3, 5, 7, 2, 4, 6], night: [5, 7, 2, 4, 6, 1, 3] },
  1: { day: [2, 4, 6, 1, 3, 5, 7], night: [6, 1, 3, 5, 7, 2, 4] },
  2: { day: [3, 5, 7, 2, 4, 6, 1], night: [7, 2, 4, 6, 1, 3, 5] },
  3: { day: [4, 6, 1, 3, 5, 7, 2], night: [1, 3, 5, 7, 2, 4, 6] },
  4: { day: [5, 7, 2, 4, 6, 1, 3], night: [2, 4, 6, 1, 3, 5, 7] },
  5: { day: [6, 1, 3, 5, 7, 2, 4], night: [3, 5, 7, 2, 4, 6, 1] },
  6: { day: [7, 2, 4, 6, 1, 3, 5], night: [4, 6, 1, 3, 5, 7, 2] },
};

export function getRuler(weekday, number, period) {
  // The Saturday source lists 5 for the daytime ruler of entry 22.
  if (weekday === 6 && number === 22 && period === 'day') return 5;
  return rulers[weekday][period][(number - 1) % 7];
}

export function toMinutes(time) {
  const [hours, minutes, seconds = 0] = time.split(':').map(Number);
  return hours * 60 + minutes + seconds / 60;
}

export function windowsFor(anchor, limit) {
  return Array.from({ length: 30 }, (_, index) => {
    const start = anchor + index * slotMinutes;
    return { number: index + 1, start, end: Math.min(start + slotMinutes, limit) };
  });
}

export const myanmarUtcOffset = 390;
const minutesPerDay = 1440;
const radians = Math.PI / 180;

// NOAA/Meeus solar declination and equation of time, evaluated at each event.
function solarPosition(julianDay) {
  const centuries = (julianDay - 2451545) / 36525;
  const meanLongitude = ((280.46646 + centuries * (36000.76983 + 0.0003032 * centuries)) % 360) * radians;
  const anomaly = (357.52911 + centuries * (35999.05029 - 0.0001537 * centuries)) * radians;
  const eccentricity = 0.016708634 - centuries * (0.000042037 + 0.0000001267 * centuries);
  const center = Math.sin(anomaly) * (1.914602 - centuries * (0.004817 + 0.000014 * centuries))
    + Math.sin(2 * anomaly) * (0.019993 - 0.000101 * centuries)
    + Math.sin(3 * anomaly) * 0.000289;
  const omega = (125.04 - 1934.136 * centuries) * radians;
  const longitude = meanLongitude + (center - 0.00569 - 0.00478 * Math.sin(omega)) * radians;
  const obliquity = (23.439291111 - centuries * (0.013004167
    + centuries * (0.000000164 - 0.000000504 * centuries))
    + 0.00256 * Math.cos(omega)) * radians;
  const declination = Math.asin(Math.sin(obliquity) * Math.sin(longitude));
  const y = Math.tan(obliquity / 2) ** 2;
  const equation = y * Math.sin(2 * meanLongitude) - 2 * eccentricity * Math.sin(anomaly)
    + 4 * eccentricity * y * Math.sin(anomaly) * Math.cos(2 * meanLongitude)
    - 0.5 * y ** 2 * Math.sin(4 * meanLongitude)
    - 1.25 * eccentricity ** 2 * Math.sin(2 * anomaly);
  return { declination, equationMinutes: 4 * equation / radians };
}

export function solarTimes(date, latitude, longitude) {
  const julianDay = Date.parse(date + 'T00:00:00Z') / 86400000 + 2440587.5;
  const latitudeRadians = latitude * radians;
  const solarNoon = 720 - 4 * longitude;
  // A 90.833° zenith includes the Sun's radius and standard horizon refraction.
  const horizon = Math.cos(90.833 * radians);

  function event(direction) {
    let utcMinutes = solarNoon;
    for (let pass = 0; pass < 4; pass += 1) {
      const { declination, equationMinutes } = solarPosition(julianDay + utcMinutes / minutesPerDay);
      const cosine = (horizon - Math.sin(latitudeRadians) * Math.sin(declination))
        / (Math.cos(latitudeRadians) * Math.cos(declination));
      if (Math.abs(cosine) > 1) return NaN;
      utcMinutes = solarNoon + direction * 4 * Math.acos(cosine) / radians - equationMinutes;
    }
    return Math.round((utcMinutes + myanmarUtcOffset) * 60) / 60;
  }

  return { sunrise: event(-1), sunset: event(1) };
}
